const ROLE_SECTORS={'AI / ML':['ai'],'סייבר':['cyber'],'Data / BI':['data'],'DevOps / Cloud':['devtools'],'Embedded':['hardware']};
const REGION_CITIES={'תל אביב':['Tel Aviv'],'גוש דן והמרכז':['Tel Aviv','Ramat Gan','Petah Tikva','Herzliya','Rehovot','Rosh HaAyin','Lod','Yavne','Airport City'],'השרון':['Herzliya',"Ra'anana",'Netanya','Kfar Saba'],'ירושלים':['Jerusalem'],'חיפה והצפון':['Haifa','Yokneam','Migdal HaEmek','Tefen','Karmiel'],'באר שבע והדרום':['Beer Sheva']};
/* שורת הסיכום של "מה מחפשים בשבילך": תגיות קצרות */
function planTags(){const a=ans(),rt=realTargets(),n=rt?rt.length:targetCompanies().length;
  return [...(a.roles&&a.roles.length?a.roles.slice(0,3):[domainOf(a)]),...(a.locs||[]).slice(0,2),a.mode&&a.mode!=='לא משנה'?a.mode:'',n?`${n} חברות יעד`:''].filter(Boolean)}
function planAlert(){const rt=realTargets()||[],k=rt.filter(b=>b.status==='confirm'||b.status==='not_found').length;
  return k?`<span class="plan-alert">${k===1?'חברה אחת צריכה בדיקה שלך':k+' חברות צריכות בדיקה שלך'}</span>`:''}
function planWhy(){
  const a=ans(),w=[];
  w.push(a.status==='סטודנט/ית'?(a.track==='משרה מלאה אחרי התואר'?'משרות ג׳וניור למשרה מלאה אחרי התואר':'משרות סטודנט, התמחויות וג׳וניור')
    :a.status?{'בוגר/ת טרי/ה, מחפש/ת עבודה ראשונה':'משרה ראשונה: ג׳וניור','משתחרר/ת משירות':'משרה ראשונה: ג׳וניור','ג׳וניור עם ניסיון של עד שנתיים':'משרות ג׳וניור'}[a.status]||'משרות לפי הניסיון שלך'
    :'משרות ג׳וניור, עד שתספר לנו מה המצב שלך');
  if(domainOf(a)!=='פיתוח תוכנה')w.push('תחום: '+domainOf(a));
  w.push(a.roles&&a.roles.length?'בתפקידים: '+a.roles.join(', '):(domainOf(a)==='פיתוח תוכנה'?'בכל תפקידי הפיתוח':`בכל התפקידים ב${domainOf(a)}`)+', עד שתבחר תפקידים');
  if((S.accepted||[]).length) w.push('תפקידים שאישרת מההצעות: '+S.accepted.map(x=>x.value).join(', '));
  w.push(a.locs&&a.locs.length?'באזורים: '+a.locs.join(', ')+(a.mode==='מהבית'?', מהבית בלבד':''):'בכל הארץ');
  if(a.exp) w.push(`בלי משרות שדורשות יותר ניסיון ממה שיש לך (${a.exp})`);
  if(learnedChips().some(([r,n])=>r==='בכירה מדי'&&n>=2)) w.push('דילגת על משרות בכירות, אז מסננים חזק יותר');
  return w;
}
function targetCompanies(){
  const a=ans(),tc=S.targets||{added:[],removed:[]},sectors=new Set((a.roles||[]).flatMap(r=>ROLE_SECTORS[r]||[]).concat((a.prio||[]).includes('טכנולוגיות מעניינות')?['ai']:[]));
  const cities=new Set((a.locs||[]).flatMap(r=>REGION_CITIES[r]||[])),junior=a.status!=='עובד/ת ומחפש/ת לעבור';
  const size=(a.prio||[]).includes('סטארט-אפ קטן')?['startup','scaleup']:(a.prio||[]).includes('חברה גדולה ויציבה')?['enterprise']:[];
  const added=new Set(tc.added.map(x=>x.toLowerCase()));
  const dk=domKey(a);const out=CATALOG.filter(c=>(c.domains||['software']).includes(dk)&&!tc.removed.includes(c.name)&&!added.has(c.name.toLowerCase())).map(c=>{let s=0;const why=[];
    if(c.sectors.some(x=>sectors.has(x))){s+=3;why.push('בתחום שבחרת')}
    if(size.includes(c.size)){s+=2;why.push({startup:'סטארט-אפ',scaleup:'חברה צומחת',enterprise:'חברה גדולה'}[c.size])}
    if(!cities.size||cities.has(c.city)||a.mode==='מהבית')s+=1;else s-=2;
    if(c.hires_juniors&&junior){s+=2;why.push('מגייסת ג׳וניורים')}
    return{...c,s,why}}).filter(c=>c.s>0).sort((x,y)=>y.s-x.s).slice(0,12);
  return [...tc.added.map(n=>({name:n,why:['הוספת בעצמך']})),...out];
}
function removeTarget(n){S.targets=S.targets||{added:[],removed:[]};S.targets.added=S.targets.added.filter(x=>x!==n);if(!S.targets.removed.includes(n))S.targets.removed.push(n);save();renderProfile();toast(`${n} הוסרה מחברות היעד`)}
function addTarget(){const el=$('tgIn'),v=el.value.trim();if(!v){el.focus();return}S.targets=S.targets||{added:[],removed:[]};S.targets.removed=S.targets.removed.filter(x=>x!==v);if(!S.targets.added.includes(v))S.targets.added.unshift(v);save();renderProfile();toast(`${v} נוספה. ${N('hunter')} יבדוק אותה בחיפוש הבא`)}

/* החברות כפי שדורון באמת בדק אותן בסריקה האחרונה: סטטוס אמיתי לכל אחת */
function realTargets(){
  if(typeof RUNS==='undefined'||!RUNS)return null;
  const h=RUNS.find(r=>(r.agent||'hunter')==='hunter'&&r.stats&&Array.isArray(r.stats.boards));if(!h)return null;
  const tc=S.targets||{added:[],removed:[]},rem=new Set(tc.removed.map(x=>x.toLowerCase())),seen=new Set();
  const out=h.stats.boards.filter(b=>!rem.has(b.name.toLowerCase())).map(b=>{seen.add(b.name.toLowerCase());return b});
  tc.added.filter(n=>!seen.has(n.toLowerCase())).forEach(n=>out.unshift({name:n,status:'new',why:['הוספת בעצמך']}));
  return out;
}

/* חברות יעד: מקובצות לפי איך שדורון באמת בודק אותן */
const bd=t=>`<bdi dir="ltr">${escB(t)}</bdi>`;
function targetsHtml(rt){
  const G={fix:[],board:[],name:[],pending:[],confirm:[]};
  const tc=S.targets||{},dec=n=>{const k=n.toLowerCase();return Object.keys(tc.boards||{}).some(x=>x.toLowerCase()===k)?'yes':Object.keys(tc.reject||{}).some(x=>x.toLowerCase()===k)?'no':''};
  rt.forEach(b=>{if(b.status==='confirm'){const d=dec(b.name);if(d){G.pending.push({...b,status:d==='yes'?'confirmed':'rejected'});return}TG_FOUND[b.name]=b.found;G.confirm.push(b);return}
    (b.status==='not_found'?G.fix:b.status==='board'?G.board:(b.status==='pending'||b.status==='new')?G.pending:G.name).push(b)});
  const x=b=>`<button class="tg-x" aria-label="להסיר את ${escB(b.name)}" onclick="removeTarget('${escB(b.name).replace(/'/g,"\\'")}')">×</button>`;
  const q=n=>escB(n).replace(/'/g,"\\'");
  const sec=(t,sub,body)=>body?`<div class="tg-sec"><div class="tg-sec-h"><b>${t}</b>${sub?`<span>${sub}</span>`:''}</div>${body}</div>`:'';
  return `<div class="tg-sum"><span><b class="num">${G.board.length}</b> נסרקות ישירות</span><span><b class="num">${G.name.length}</b> לפי שם</span>${G.fix.length?`<span class="bad"><b class="num">${G.fix.length}</b> צריך לבדוק</span>`:''}</div>`
   +sec('זו החברה?',`${escB(N('hunter'))} מצא דף קריירה, אבל השם לא זהה. לא סורקים עד שתאשר`,G.confirm.map(b=>`<div class="tg-fix"><div><b>${bd(b.name)}</b><span>נמצא באתר <a class="ext" href="${escB(b.found.url)}" target="_blank" rel="noopener">${bd(b.found.host)}</a></span></div>
      <div class="tg-fix-btns"><button class="btn btn-sm btn-primary" onclick="confirmTarget('${q(b.name)}',true)">כן, זו החברה</button><button class="btn btn-sm btn-ghost" onclick="confirmTarget('${q(b.name)}',false)">לא</button></div></div>`).join(''))
   +sec('צריך לבדוק','',G.fix.map(b=>`<div class="tg-fix"><div><b>${bd(b.name)}</b><span>לא נמצאה חברה בשם הזה${b.suggest?`. התכוונת ל-${bd(b.suggest)}?`:'.'}</span></div>
      <div class="tg-fix-btns">${b.suggest?`<button class="btn btn-sm btn-primary" onclick="renameTarget('${q(b.name)}','${q(b.suggest)}')">לתקן ל-${bd(b.suggest)}</button>`:''}<button class="btn btn-sm btn-ghost" onclick="editTarget('${q(b.name)}')">לערוך</button>${x(b)}</div></div>`).join(''))
   +sec('נסרקות ישירות מדף הקריירה','כל המשרות בישראל, בלי חסימות',`<div class="tg-grid">${G.board.map(b=>`<div class="tg-chip ok"><b>${bd(b.name)}</b><span>${b.rel} בתחום שלך, מתוך ${b.il} בישראל</span><span class="tg-src">דרך ${bd(b.board)}</span>${x(b)}</div>`).join('')}</div>`)
   +sec('מחפשים לפי השם','ב-LinkedIn וב-Indeed, כי אין להן דף קריירה ציבורי',`<div class="tg-grid">${G.name.map(b=>`<div class="tg-chip"><b>${bd(b.name)}</b><span>${b.status==='by_name_ok'?`${b.n} משרות בתחום שלך`+(b.found_as?`</span><span class="tg-src">במודעות: ${bd(b.found_as)}`:''):b.status==='by_name_miss'?'הפעם לא עלו משרות בתחום שלך':'ייבדק בסריקה הקרובה'}</span>${b.official?`<span class="tg-src">האתר שלה: ${bd(b.official)}</span>`:''}${x(b)}</div>`).join('')}</div>`)
   +sec('ייבדקו בסריקה הקרובה','',`<div class="tg-grid">${G.pending.map(b=>`<div class="tg-chip"><b>${bd(b.name)}</b><span>${b.status==='new'?'הוספת עכשיו':b.status==='confirmed'?'אישרת. תיסרק מהאתר שלה':b.status==='rejected'?'דחית. נחפש שוב':'בתור'}</span>${x(b)}</div>`).join('')}</div>`);
}
const TG_FOUND={};
function confirmTarget(n,yes){const f=TG_FOUND[n];if(!f)return;S.targets=S.targets||{added:[],removed:[]};
  if(yes){S.targets.boards=Object.assign({},S.targets.boards,{[n]:f.board});toast(`${N('hunter')} יסרוק את ${n} מ-${f.host} בסריקה הבאה`)}
  else{S.targets.reject=Object.assign({},S.targets.reject);S.targets.reject[n]=[...(S.targets.reject[n]||[]),f.url];toast(`הבנתי. ${N('hunter')} יחפש את ${n} במקום אחר`)}
  save();renderProfile()}
function renameTarget(from,to){to=(to||'').trim();if(!to||to===from)return;S.targets=S.targets||{added:[],removed:[]};
  const i=S.targets.added.indexOf(from);if(i>=0)S.targets.added[i]=to;else{S.targets.added.unshift(to);if(!S.targets.removed.includes(from))S.targets.removed.push(from)}
  S.targets.removed=S.targets.removed.filter(x=>x!==to);save();renderProfile();toast(`עודכן ל-${to}. ${N('hunter')} יבדוק אותה בסריקה הבאה`)}
function editTarget(n){openSheet(`<h3 id="sheetTitle">תיקון שם חברה</h3><div class="sheet-sub">כמו שהיא מופיעה ב-LinkedIn או באתר שלה</div>
  <div class="field" style="margin-top:12px"><label for="tgEd" class="vh">שם החברה</label><input id="tgEd" class="ltr" value="${escB(n)}"></div>
  <button class="btn btn-primary btn-block" onclick="renameTarget('${escB(n).replace(/'/g,"\\'")}',$('tgEd').value);closeSheet()">שמירה</button>`)}
